/// `M_PointToAngle`-free helper: the mobj type spawned by a map thing's
/// `doomednum` (`P_SpawnMapThing`'s `mobjinfo[i].doomednum` scan).
pub fn mobj_type_for_doomednum(doomednum: i32) -> Option<MobjType> {
    MOBJINFO
        .iter()
        .position(|m| m.doomednum == doomednum)
        .map(|i| MOBJTYPES[i])
}

