#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_match_c() {
        assert_eq!(STATES.len(), NUMSTATES as usize);
        assert_eq!(MOBJINFO.len(), NUMMOBJTYPES as usize);
        assert_eq!(SPRNAMES.len(), NUMSPRITES as usize);
    }

    #[test]
    fn player_mobjinfo() {
        let p = &MOBJINFO[MobjType::MT_PLAYER as usize];
        assert_eq!(p.doomednum, -1);
        assert_eq!(p.spawnhealth, 100);
        assert_eq!(p.radius, 16 << 16);
        assert_eq!(p.height, 56 << 16);
        assert_eq!(p.spawnstate, StateId::S_PLAY);
        assert_eq!(p.flags, 2 | 4 | 0x400 | 0x800 | 0x2000000);
    }

    #[test]
    fn weaponinfo_order() {
        assert_eq!(WEAPONINFO[0].ammo, None); // fist
        assert_eq!(WEAPONINFO[1].ammo, Some(AmmoType::Clip)); // pistol
        assert_eq!(WEAPONINFO[2].ammo, Some(AmmoType::Shell)); // shotgun
        assert_eq!(WEAPONINFO[3].ammo, Some(AmmoType::Clip)); // chaingun
        assert_eq!(WEAPONINFO[4].ammo, Some(AmmoType::Missile)); // launcher
        assert_eq!(WEAPONINFO[2].readystate, StateId::S_SGUN);
    }

    #[test]
    fn actions_counts() {
        let nonnull = STATES.iter().filter(|s| s.action != Action::Null).count();
        assert!((400..500).contains(&nonnull), "nonnull={nonnull}");
        assert_eq!(STATES[0].nextstate, StateId::S_NULL);
        assert_eq!(STATES[StateId::S_PUNCH as usize].tics, 1);
    }

    #[test]
    fn sprite_names_line_up() {
        assert_eq!(SPRNAMES[0], "TROO");
        assert_eq!(SPRNAMES[Sprite::SPR_TROO as usize], "TROO");
        assert_eq!(SPRNAMES[Sprite::SPR_TLP2 as usize], "TLP2");
    }
}


